/**
 * Data-driven recommendations and roadmap. Everything here is ADVISORY: it is generated by
 * transparent rules from the assessment results and must be validated with the client. No
 * financial benefit is quoted and nothing is presented as statistically validated.
 *
 * Generated recommendations have stable IDs. User edits (priority, owner, status, notes, bucket,
 * text) are stored as overrides keyed by that ID so they survive regeneration.
 */
import { DIMENSION_BY_ID, DIMENSIONS, QUESTION_BY_ID, QUESTIONS, type DimensionId } from '../data/spec';
import type { Bucket, CustomRec, Priority, RecOverride, RecStatus, Response } from '../domain/schema';
import type { CrossCheckFlag } from './crosscheck';
import type { GateResult } from './gates';
import type { IndexResult } from './maturity';
import type { IndiaResult } from './india';
import type { IndicatorsComputation } from './indicators';
import { evalQuestion } from './questionState';

export const BUCKET_LABELS: Record<Bucket, string> = { m0_6: '0–6 months', m6_12: '6–12 months', m12_24: '12–24 months' };
export const PRIORITY_RANK: Record<Priority, number> = { critical: 0, high: 1, medium: 2, low: 3 };
export const PRIORITY_LABELS: Record<Priority, string> = { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low' };
export const STATUS_LABELS: Record<RecStatus, string> = {
  not_started: 'Not started',
  in_progress: 'In progress',
  completed: 'Completed',
  deferred: 'Deferred',
  dismissed: 'Dismissed',
};

export type RecKind = 'critical_control' | 'dimension_gap' | 'evidence_gap' | 'enhancement' | 'validation' | 'india' | 'custom';

export interface Recommendation {
  id: string;
  kind: RecKind;
  title: string;
  priority: Priority;
  dimensionId: DimensionId | null;
  questionIds: string[];
  gap: string;
  why: string;
  intervention: string;
  role: string;
  timeframe: string;
  bucket: Bucket;
  dependencies: string;
  kpi: string;
  /** Question IDs (or descriptions) of related evidence gaps. */
  evidenceGaps: string[];
  basisNote: string;
  rankScore: number;
  status: RecStatus;
  owner: string;
  notes: string;
  isCustom: boolean;
  edited: boolean;
}

interface DimLibrary {
  role: string;
  why: string;
  interventions: string[];
  kpi: string;
  dependencies: string;
}

