export interface RecContext {
  responses: Record<string, Response>;
  maturityVerified: IndexResult;
  maturitySelf: IndexResult;
  gates: GateResult;
  indicators: IndicatorsComputation;
  crossChecks: CrossCheckFlag[];
  india: IndiaResult;
  coverageDimensionsInsufficient: DimensionId[];
}

const TARGET = 3;
const FOUNDATIONAL: DimensionId[] = ['S', 'G', 'D', 'R', 'C'];

const truncate = (s: string, n = 110) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);

/** Effective score used for recommendations: verified where available, otherwise self-reported (flagged). */
function effective(r: Response): { score: number | null; basis: 'verified' | 'self-reported' | null } {
  const v = evalQuestion(r, 'verified');
  if (v.state === 'scored') return { score: v.score, basis: 'verified' };
  const s = evalQuestion(r, 'self');
  if (s.state === 'scored' && v.state !== 'not_applicable') return { score: s.score, basis: 'self-reported' };
  return { score: null, basis: null };
}

function bucketFor(priority: Priority, dimensionId: DimensionId | null, kind: RecKind): Bucket {
  if (kind === 'enhancement') return 'm12_24';
  if (priority === 'critical') return 'm0_6';
  if (priority === 'high') return dimensionId && FOUNDATIONAL.includes(dimensionId) ? 'm0_6' : 'm6_12';
  if (priority === 'medium') return 'm6_12';
  return 'm12_24';
}

export function generateRecommendations(ctx: RecContext): Recommendation[] {
  const recs: Recommendation[] = [];
  const base = (r: Omit<Recommendation, 'timeframe' | 'status' | 'owner' | 'notes' | 'isCustom' | 'edited'>): Recommendation => ({
    ...r,
    timeframe: BUCKET_LABELS[r.bucket],
    status: 'not_started',
    owner: '',
    notes: '',
    isCustom: false,
    edited: false,
  });

  // 1. Critical control deficiencies (verified) -----------------------------------------
  const covered = new Set<string>();
  const byGate = new Map<string, typeof ctx.gates.deficiencies>();
  for (const d of ctx.gates.deficiencies) byGate.set(d.gateId, [...(byGate.get(d.gateId) ?? []), d]);
  for (const [gateId, defs] of byGate) {
    const lib = GATE_LIB[gateId];
    if (!lib) continue;
    const qids = defs.map((d) => d.questionId);
    qids.forEach((q) => covered.add(q));
    const dim = defs[0].dimensionId;
    recs.push(
      base({
        id: `crit-${gateId}`,
        kind: 'critical_control',
        title: lib.title,
        priority: 'critical',
        dimensionId: dim,
        questionIds: qids,
        gap: `Verified at or below the deficiency threshold (≤ ${ctx.gates.threshold}): ${defs
          .map((d) => `${d.questionId} (${d.verifiedScore}) — ${truncate(d.text, 90)}`)
          .join('; ')}.`,
        why: lib.why,
        intervention: lib.interventions.join(' '),
        role: lib.role,
        dependencies: lib.dependencies,
        kpi: lib.kpi,
        evidenceGaps: defs.filter((d) => d.evidenceStatus !== 'accepted').map((d) => d.questionId),
        basisNote: 'Based on assessor-verified scores.',
        bucket: 'm0_6',
        rankScore: 1000 + defs.length * 10,
      }),
    );
  }

  // 2. Critical controls with only a self-reported deficiency or no verification ----------
  const toVerify = ctx.gates.unverified;
  if (ctx.gates.enabled && toVerify.length > 0) {
    const qids = toVerify.map((c) => c.questionId);
    recs.push(
      base({
        id: 'verify-critical-controls',
        kind: 'evidence_gap',
        title: 'Verify critical security, privacy and responsible-AI controls',
        priority: 'high',
        dimensionId: null,
        questionIds: qids,
        gap: `${toVerify.length} critical control${toVerify.length > 1 ? 's have' : ' has'} no assessor-verified score${toVerify.some((c) => c.severity === 'self_reported_deficient') ? ` (${toVerify.filter((c) => c.severity === 'self_reported_deficient').length} self-reported as deficient)` : ''}: ${qids.join(', ')}.`,
        why: 'The maturity gate cannot be cleared with confidence while critical controls are unverified; self-reported deficiencies may represent real exposure.',
        intervention: 'Schedule assessor walkthroughs and document review for each unverified critical control; record the verified score and evidence status.',
        role: 'Lead assessor with CISO / DPO / Responsible AI lead',
        dependencies: 'Access to control owners and evidence.',
        kpi: '100% of critical controls with an assessor-verified score and recorded evidence status.',
        evidenceGaps: qids,
        basisNote: 'Evidence gap — not a scored deficiency.',
        bucket: 'm0_6',
        rankScore: 900 + toVerify.length,
      }),
    );
  }

  // 3. Dimension gaps ------------------------------------------------------------------
  for (const dim of DIMENSIONS) {
    const qs = QUESTIONS.filter((q) => q.dimensionId === dim.id);
    const scored = qs
      .map((q) => ({ q, e: effective(ctx.responses[q.id]) }))
      .filter((x): x is { q: (typeof qs)[number]; e: { score: number; basis: 'verified' | 'self-reported' } } => x.e.score !== null);
    if (scored.length === 0) continue;
    const gaps = scored.filter((x) => x.e.score < TARGET && !covered.has(x.q.id)).sort((a, b) => a.e.score - b.e.score);
    if (gaps.length === 0) continue;
    const mean = scored.reduce((a, x) => a + x.e.score, 0) / scored.length;
    const impact = dim.weight * Math.max(0, TARGET - mean) / TARGET;
    const priority: Priority = impact >= 2 ? 'high' : impact >= 0.8 ? 'medium' : 'low';
    const lib = LIB[dim.id];
    const selfCount = gaps.filter((g) => g.e.basis === 'self-reported').length;
    const shown = gaps.slice(0, 6);
    recs.push(
      base({
        id: `dim-${dim.id}`,
        kind: 'dimension_gap',
        title: `Strengthen ${dim.name}`,
        priority,
        dimensionId: dim.id,
        questionIds: shown.map((g) => g.q.id),
        gap: `${gaps.length} question${gaps.length > 1 ? 's are' : ' is'} below Established (3): ${shown
          .map((g) => `${g.q.id} (${g.e.score})`)
          .join(', ')}${gaps.length > shown.length ? ` and ${gaps.length - shown.length} more` : ''}. Weakest: ${shown[0].q.id} — ${truncate(shown[0].q.text)} Dimension mean ${mean.toFixed(2)} of 4; weight ${dim.weight}%.`,
        why: lib.why,
        intervention: lib.interventions.join(' '),
        role: lib.role,
        dependencies: lib.dependencies,
        kpi: lib.kpi,
        evidenceGaps: gaps.filter((g) => ctx.responses[g.q.id].evidence.status !== 'accepted').map((g) => g.q.id),
        basisNote: selfCount > 0 ? `Includes ${selfCount} self-reported (not yet verified) score${selfCount > 1 ? 's' : ''}.` : 'Based on assessor-verified scores.',
        bucket: bucketFor(priority, dim.id, 'dimension_gap'),
        rankScore: 100 + impact * 10 + (FOUNDATIONAL.includes(dim.id) ? 5 : 0),
      }),
    );
  }

  // 4. Evidence / coverage gaps ----------------------------------------------------------
  for (const id of ctx.coverageDimensionsInsufficient) {
    const dim = DIMENSION_BY_ID[id];
    const qs = QUESTIONS.filter((q) => q.dimensionId === id);
    const open = qs.filter((q) => {
      const e = evalQuestion(ctx.responses[q.id], 'verified');
      return e.state === 'pending' || e.state === 'unverified';
    });
    if (open.length === 0) continue;
    const priority: Priority = dim.weight >= 10 ? 'high' : 'medium';
    recs.push(
      base({
        id: `evid-${id}`,
        kind: 'evidence_gap',
        title: `Complete verification for ${dim.name}`,
        priority,
        dimensionId: id,
        questionIds: open.map((q) => q.id),
        gap: `${open.length} of ${qs.length} questions have no assessor-verified score (${open.map((q) => q.id).join(', ')}), so the dimension score is ${ctx.maturityVerified.dimensions.find((d) => d.id === id)?.status === 'unscored' ? 'unscored' : 'partial'} and the overall index is provisional.`,
        why: 'Self-reported scores are not a substitute for verified evidence; coverage gaps make the index provisional and weaken benchmarking.',
        intervention: 'Collect supporting documents or demonstrations, schedule stakeholder interviews and record verified scores and evidence status for each open question.',
        role: 'Lead assessor with the dimension owner',
        dependencies: 'Respondent availability; evidence access.',
        kpi: `Verified coverage of at least the configured threshold for ${dim.shortName}; evidence accepted for each scored question.`,
        evidenceGaps: open.map((q) => q.id),
        basisNote: 'Evidence gap — not a scored deficiency.',
        bucket: 'm0_6',
        rankScore: 600 + dim.weight,
      }),
    );
  }

  // Rejected / clarification evidence
  const evidenceIssues = QUESTIONS.filter((q) => ['rejected', 'clarification'].includes(ctx.responses[q.id].evidence.status));
  if (evidenceIssues.length > 0) {
    recs.push(
      base({
        id: 'evid-quality',
        kind: 'evidence_gap',
        title: 'Resolve rejected and clarification-required evidence',
        priority: 'medium',
        dimensionId: null,
        questionIds: evidenceIssues.map((q) => q.id),
        gap: `${evidenceIssues.length} question${evidenceIssues.length > 1 ? 's have' : ' has'} evidence that was rejected or needs clarification: ${evidenceIssues.map((q) => q.id).join(', ')}.`,
        why: 'Unresolved evidence leaves the associated scores unsupported.',
        intervention: 'Request replacement or clarifying evidence from the respondent and re-review; adjust verified scores if evidence cannot be supported.',
        role: 'Lead assessor',
        dependencies: 'Respondent follow-up.',
        kpi: 'All rejected / clarification items resolved to accepted evidence or a revised verified score.',
        evidenceGaps: evidenceIssues.map((q) => q.id),
        basisNote: 'Evidence gap.',
        bucket: 'm0_6',
        rankScore: 550,
      }),
    );
  }

  // 5. Quantitative cross-check discrepancies ---------------------------------------------
  if (ctx.crossChecks.length > 0) {
    recs.push(
      base({
        id: 'validate-crosschecks',
        kind: 'validation',
        title: 'Reconcile questionnaire scores with quantitative indicators',
        priority: 'medium',
        dimensionId: null,
        questionIds: Array.from(new Set(ctx.crossChecks.map((c) => c.questionId))),
        gap: `${ctx.crossChecks.length} score${ctx.crossChecks.length > 1 ? 's are' : ' is'} not corroborated by the related indicator: ${ctx.crossChecks.map((c) => `${c.questionId} vs ${c.indicatorName}`).join('; ')}.`,
        why: 'Source guidance is that quantitative indicators validate self-reported maturity; unexplained gaps indicate over-statement or measurement problems.',
        intervention: 'Re-test the affected questions with the respondents and review how each indicator was measured; amend verified scores where warranted.',
        role: 'Lead assessor',
        dependencies: 'Indicator source data.',
        kpi: 'All flagged discrepancies resolved or explained in assessor observations.',
        evidenceGaps: [],
        basisNote: 'Heuristic prompt — not a scored deficiency.',
        bucket: 'm0_6',
        rankScore: 500,
      }),
    );
  }

  // 6. Measurement capability ------------------------------------------------------------
  if (ctx.indicators.captured < 8) {
    recs.push(
      base({
        id: 'measure-indicators',
        kind: 'validation',
        title: 'Establish measurement of the quantitative AI indicators',
        priority: 'medium',
        dimensionId: 'V',
        questionIds: ['V04', 'V05'],
        gap: `Only ${ctx.indicators.captured} of ${ctx.indicators.total} source indicators have been captured with valid inputs. Value Realization and benchmarking depend on measurable evidence.`,
        why: 'The source recommends a separate set of measurable indicators to validate maturity and enable credible benchmarking.',
        intervention: 'Define owners, data sources and reporting periods for each indicator; capture numerator, denominator and period consistently.',
        role: 'CFO / Head of AI measurement',
        dependencies: 'Finance and HR data access.',
        kpi: 'At least 12 of 15 indicators captured with a common reporting period.',
        evidenceGaps: [],
        basisNote: 'Evidence gap.',
        bucket: 'm6_12',
        rankScore: 150,
      }),
    );
  }

  // 7. India-specific diagnostics --------------------------------------------------------
  const indiaWeak = ctx.india.items.filter((i) => i.applicability === 'applicable' && (i.verifiedScore ?? i.selfScore) !== null && (i.verifiedScore ?? i.selfScore)! < TARGET);
  if (indiaWeak.length > 0) {
    recs.push(
      base({
        id: 'india-gaps',
        kind: 'india',
        title: 'Address India-specific diagnostic gaps',
        priority: 'medium',
        dimensionId: null,
        questionIds: [],
        gap: `Applicable India-specific areas below Established: ${indiaWeak.map((i) => `${i.area} (${i.verifiedScore ?? i.selfScore})`).join('; ')}.`,
        why: 'India-specific regulatory, language, public-infrastructure and sovereignty considerations affect lawful and effective AI deployment. This is a diagnostic observation, not a legal opinion.',
        intervention: 'Confirm obligations in force at the assessment date with counsel, then close the identified gaps through governance, data-location and language-capability workstreams.',
        role: 'General Counsel / DPO with the AI governance lead',
        dependencies: 'Legal confirmation of applicable obligations.',
        kpi: 'Applicable India-specific areas re-assessed at Established (3) or above.',
        evidenceGaps: [],
        basisNote: ctx.india.verifiedScored > 0 ? 'Based on India diagnostic scores (supplementary, outside the core index).' : 'Based on self-reported India diagnostic scores.',
        bucket: 'm6_12',
        rankScore: 140,
      }),
    );
  }

  // 8. Enhancement of strong dimensions (12–24 months) ------------------------------------
  const strong = ctx.maturityVerified.dimensions
    .filter((d) => d.mean !== null && d.mean >= TARGET && d.mean < 3.75)
    .sort((a, b) => b.weight - a.weight)
    .slice(0, 3);
  for (const d of strong) {
    const dim = DIMENSION_BY_ID[d.id];
    const lib = LIB[d.id];
    recs.push(
      base({
        id: `enh-${d.id}`,
        kind: 'enhancement',
        title: `Advance ${dim.name} toward enterprise-wide, measured optimization`,
        priority: 'low',
        dimensionId: d.id,
        questionIds: QUESTIONS.filter((q) => q.dimensionId === d.id && (effective(ctx.responses[q.id]).score ?? 4) < 4).map((q) => q.id).slice(0, 6),
        gap: `${dim.shortName} is verified at a mean of ${d.mean!.toFixed(2)} of 4 (Established). Advanced maturity requires enterprise-wide coverage, measurement and continuous improvement.`,
        why: 'Material enhancement rather than a deficiency; sequence after critical controls and evidence gaps are addressed.',
        intervention: lib.interventions[0] + ' Extend measurement and continuous-improvement loops across all relevant functions.',
        role: lib.role,
        dependencies: 'Completion of 0–12 month priorities.',
        kpi: lib.kpi,
        evidenceGaps: [],
        basisNote: 'Based on assessor-verified scores.',
        bucket: 'm12_24',
        rankScore: 10 + d.weight,
      }),
    );
  }

  recs.sort((a, b) => PRIORITY_RANK[a.priority] - PRIORITY_RANK[b.priority] || b.rankScore - a.rankScore);
  return recs;
}

/** Layer persisted user edits and custom initiatives over the generated list. */
export function applyOverrides(generated: Recommendation[], overrides: Record<string, RecOverride>, custom: CustomRec[]): Recommendation[] {
  const merged = generated.map((r) => {
    const o = overrides[r.id];
    if (!o) return r;
    const next: Recommendation = { ...r, edited: Object.keys(o).length > 0 };
    if (o.priority) next.priority = o.priority;
    if (o.status) next.status = o.status;
    if (o.owner !== undefined) next.owner = o.owner;
    if (o.notes !== undefined) next.notes = o.notes;
    if (o.bucket) {
      next.bucket = o.bucket;
      if (o.timeframe === undefined) next.timeframe = BUCKET_LABELS[o.bucket];
    }
    for (const f of ['title', 'gap', 'why', 'intervention', 'role', 'timeframe', 'dependencies', 'kpi'] as const) {
      if (o[f] !== undefined) next[f] = o[f] as string;
    }
    return next;
  });
  const customs: Recommendation[] = custom.map((c) => ({
    id: c.id,
    kind: 'custom',
    title: c.title,
    priority: c.priority,
    dimensionId: (c.dimensionId || null) as DimensionId | null,
    questionIds: c.questionIds,
    gap: c.gap,
    why: c.why,
    intervention: c.intervention,
    role: c.role,
    timeframe: c.timeframe || BUCKET_LABELS[c.bucket],
    bucket: c.bucket,
    dependencies: c.dependencies,
    kpi: c.kpi,
    evidenceGaps: [],
    basisNote: 'Added by the assessor.',
    rankScore: 0,
    status: c.status,
    owner: c.owner,
    notes: c.notes,
    isCustom: true,
    edited: false,
  }));
  return [...merged, ...customs].sort((a, b) => PRIORITY_RANK[a.priority] - PRIORITY_RANK[b.priority] || b.rankScore - a.rankScore);
}

export function roadmapBuckets(recs: Recommendation[]): Record<Bucket, Recommendation[]> {
  const out: Record<Bucket, Recommendation[]> = { m0_6: [], m6_12: [], m12_24: [] };
  for (const r of recs) if (r.status !== 'dismissed') out[r.bucket].push(r);
  return out;
}

export const ADVISORY_NOTICE =
  'Recommendations and roadmap items are advisory outputs generated by transparent rules from the assessment data. They require consulting judgement and client validation. They do not quote financial benefits, guarantee ROI, or represent statistically validated findings.';

